    private static readonly Dictionary<string, MpOperationContract> ById =
        Operations.ToDictionary(operation => operation.Descriptor.OperationId, StringComparer.Ordinal);

    public static MpOperationContract Get(string operationId) =>
        ById.TryGetValue(operationId, out var operation)
            ? operation
            : throw new InvalidOperationException($"Unknown Wave A operation '{operationId}'.");
}
